//! Tokens generated by the lexer

use libcivexec::{BasicType, operation::Operation};

use crate::{Location, program::types::LabelRef};

/// A token of the assembly program
#[derive(Clone, Default)]
pub struct Token {
    /// The value the token is carrying
    value: TokenValue,

    /// The position as range (`[start, end]`)
    position: [Location; 2],
}

impl Token {
    /// Get the tokens position
    pub fn position(&self) -> &[Location; 2] {
        &self.position
    }

    /// Get the tokens value
    pub fn value(&self) -> &TokenValue {
        &self.value
    }

    /// Get a mutable refere to the tokens value
    pub fn value_mut(&mut self) -> &mut TokenValue {
        &mut self.value
    }

    /// Create a new token from given value and position
    pub fn new(value: TokenValue, position: [Location; 2]) -> Self {
        Self { value, position }
    }
}

/// The value and type of a token
#[derive(Clone, PartialEq)]
pub enum TokenValue {
    /// Instruction code
    OpCode(Operation<LabelRef>),

    /// String
    String(String),

    /// Jump mark
    Label(String),

    /// Pseudo instruction
    Pseudo(String),

    /// Integer (64 bit)
    Int(i64),

    /// Floating point (64 bit)
    Float(f64),

    /// Boolean
    Bool(bool),

    /// Type marker for a [`BasicType`]
    BasicType(BasicType),

    /// Array of [`BasicType`] with given dimensions
    DimensionalType(BasicType, u8),

    /// End of file (required to determine end of token stream)
    EoF,
}

impl TokenValue {
    /// Get a string representation of the token type
    pub fn get_type(&self) -> &'static str {
        match self {
            TokenValue::OpCode(_) => "OpCode",
            TokenValue::String(_) => "String",
            TokenValue::Label(_) => "Label",
            TokenValue::Pseudo(_) => "Pseudo",
            TokenValue::Int(_) => "Int",
            TokenValue::Float(_) => "Float",
            TokenValue::Bool(_) => "Bool",
            TokenValue::BasicType(_) => "BasicType",
            TokenValue::DimensionalType(_, _) => "DimensionalType",
            TokenValue::EoF => "EndOfFile",
        }
    }
}

impl Default for TokenValue {
    fn default() -> Self {
        TokenValue::EoF
    }
}
